import type { SubjectBank } from '@/types';

export const sociologyBank: SubjectBank = {
  short: [
    { question: "What is socialisation?", answer: "Socialisation is the process by which people learn the norms, values, and culture of their society. Primary socialisation occurs in the family; secondary socialisation in school, peer groups, and the media.", acceptedAnswers: ["The process of learning the norms, values and culture of a society through agencies like family and school", "Socialisation is how individuals learn to fit into society — primary through family, secondary through school and peers", "Learning society's rules and values; primary socialisation in the family, secondary socialisation elsewhere", "The process through which individuals internalise the norms and values of their culture"], marks: 2, hint: "Learning how to fit into society through the family first, then other institutions" },
    { question: "What is the difference between a nuclear and an extended family?", answer: "A nuclear family consists of two parents and their dependent children. An extended family includes grandparents, aunts, uncles, and other relatives living with or near the family.", acceptedAnswers: ["Nuclear = two parents and dependent children; extended = wider relatives included such as grandparents and aunts/uncles", "Nuclear family is parents + children; extended family adds grandparents and other relatives", "A nuclear family is the small immediate household; an extended family encompasses wider kin networks", "Nuclear: just parents and children. Extended: includes grandparents, aunts, uncles and other relatives"], marks: 2, hint: "One is the small household unit; the other includes wider relatives" },
    { question: "What does 'meritocracy' mean?", answer: "Meritocracy is the idea that individuals are rewarded based on their talent, effort, and ability rather than their social background or class. Functionalists believe schools are meritocratic.", acceptedAnswers: ["A system where rewards are based on individual ability, effort, and merit rather than social class or background", "The idea that success is determined by talent and hard work, not by who you are born to", "Meritocracy means people earn their position through effort and ability, not inherited privilege", "A social system where achievement determines status — functionalists see schools as meritocratic"], marks: 2, hint: "Rewards based on merit — talent and hard work, not background" },
    { question: "What is meant by 'social class'?", answer: "Social class is a way of categorising people based on occupation, income, wealth, and education. The main classes are working class, middle class, and upper class.", acceptedAnswers: ["A hierarchy of groups based on occupation, income, wealth and education level", "Social class categorises people by their economic position — working, middle and upper class", "A system of stratification based on factors like occupation, wealth, and education", "Social class is a grouping of people who share a similar economic and social position in society"], marks: 2, hint: "A hierarchy based on occupation, wealth, and income" },
    { question: "Define 'culture' in sociological terms.", answer: "Culture refers to the shared norms, values, beliefs, customs, language, and artefacts of a society or group. It is learned through socialisation, not inherited biologically.", acceptedAnswers: ["The shared values, norms, beliefs, customs and language of a society, learned through socialisation", "Culture is the way of life of a group — including norms, values, beliefs and practices — passed on through socialisation", "Shared beliefs, customs and values that define a group or society and are transmitted socially not genetically", "The collective norms, values, customs and artefacts of a society learned through the socialisation process"], marks: 2, hint: "Shared way of life — values, norms, beliefs — passed on through socialisation" },
    { question: "What is meant by the 'dark figure' of crime?", answer: "The dark figure of crime refers to the amount of crime that is committed but never recorded in official statistics — because it goes unreported or unrecorded by the police.", acceptedAnswers: ["Crime that occurs but is not reported to or recorded by the police — missing from official statistics", "The hidden amount of crime not captured by official statistics due to under-reporting or non-recording", "Crimes that go unreported or unrecorded and therefore do not appear in official crime figures", "The gap between actual crime committed and crime that appears in official statistics"], marks: 2, hint: "All the crime we don't know about because it isn't reported or recorded" },
    { question: "What is the functionalist view of the role of education?", answer: "Functionalists (Parsons, Durkheim) argue education performs two key functions: secondary socialisation (transmitting shared values and culture) and role allocation (selecting and placing individuals in appropriate positions based on merit).", acceptedAnswers: ["Education socialises individuals into shared values and allocates roles in society based on merit (Parsons, Durkheim)", "Functionalists see education as transmitting shared values and meritocratically allocating people to suitable roles", "Education performs socialisation and role allocation functions — preparing individuals for their place in society", "Parsons: education is a bridge between family and society, socialising students and selecting them by ability"], marks: 2, hint: "Socialisation and sorting people into roles — meritocracy" },
    { question: "What is a questionnaire in sociological research?", answer: "A questionnaire is a pre-set list of written questions given to respondents. Closed questions produce quantitative data; open questions produce qualitative data. Questionnaires are cheap and efficient but may lack depth.", acceptedAnswers: ["A pre-set list of written questions; closed questions give quantitative data, open questions give qualitative data", "A research method using fixed written questions — cheap and quick but may lack depth and validity", "Written questions given to respondents to collect data; can be closed (numbers) or open (descriptions)", "A structured set of questions used to gather data from many respondents; reliable but potentially low validity"], marks: 2, hint: "Pre-set written questions — closed = numbers, open = descriptions" },
    { question: "What is the difference between absolute poverty and relative poverty?", answer: "Absolute poverty is lacking the basic necessities for survival (food, shelter, water). Relative poverty means having significantly less than the average living standard in society — being poor compared to others around you.", acceptedAnswers: ["Absolute poverty = lacking basic survival needs; relative poverty = having significantly less than the average in society", "Absolute is about survival — no food/shelter; relative is about inequality — below the social average", "Absolute poverty means you cannot meet basic needs; relative poverty means you are poor compared to others in your society", "Survival poverty is absolute; relative poverty is being much poorer than the average person around you"], marks: 2, hint: "Absolute = survival basics; relative = compared to others in society" },
    { question: "What is meant by 'secularisation'?", answer: "Secularisation is the process by which religion loses its social significance in modern society — fewer people attend church, religion has less influence on social institutions and public life.", acceptedAnswers: ["The declining importance of religion in modern society — falling church attendance and reduced influence on institutions", "Secularisation is religion becoming less significant — fewer believers, less influence on law and public life", "The process by which society becomes less religious — declining attendance, belief and institutional influence of religion", "Religion losing social significance and influence in modern societies — part of modernisation"], marks: 2, hint: "Religion becoming less important in modern society" },
    { question: "What is the 'hypodermic syringe' model of media effects?", answer: "The hypodermic syringe model proposes that the media has a direct, powerful effect on passive audiences, 'injecting' messages straight into their minds and influencing behaviour.", acceptedAnswers: ["The view that media directly and powerfully injects messages into passive audiences who simply absorb them", "Media effects model suggesting audiences passively receive media content which directly influences their behaviour", "The idea that the media injects ideas directly into viewers who have no power to resist the message", "A model claiming media has a direct, immediate effect on a passive audience — like injecting a drug"], marks: 2, hint: "Media directly injects messages into passive audiences — like a syringe" },
    { question: "What is meant by 'labelling' in the context of crime and deviance?", answer: "Labelling is when a person or group is given a negative label (e.g. 'criminal' or 'deviant') by an authoritative source. Being labelled can lead to a self-fulfilling prophecy where the person acts in accordance with the label.", acceptedAnswers: ["Attaching a negative identity (e.g. criminal) to a person; this can create a self-fulfilling prophecy", "Labelling theory: being defined as deviant by authority figures can cause someone to adopt that identity", "When powerful groups apply deviant labels to others, who may then internalise and live up to those labels", "A label such as 'criminal' applied to a person which shapes how others treat them and how they see themselves"], marks: 2, hint: "A negative label is applied; the person may then live up to it" },
    { question: "What is social mobility?", answer: "Social mobility is the movement of individuals or groups between social classes. Upward mobility means moving to a higher class; downward mobility means moving to a lower class.", acceptedAnswers: ["Movement between social classes — upward (higher class) or downward (lower class)", "The ability to move up or down the social class hierarchy through life", "Social mobility describes how easily people can change their social class position", "Movement between class positions: upward mobility rises in class, downward mobility falls"], marks: 2, hint: "Movement up or down the class hierarchy" },
    { question: "State two differences between quantitative and qualitative data.", answer: "Quantitative data is numerical, statistical, and allows comparison. Qualitative data is descriptive, explores meaning and feelings, and cannot be easily counted. Quantitative tends to be more reliable; qualitative tends to be more valid.", acceptedAnswers: ["Quantitative = numbers/statistics (reliable); qualitative = descriptions/meanings (valid)", "Quantitative data can be counted and compared; qualitative data explores feelings and is harder to generalise", "Quantitative is measurable and objective; qualitative is subjective and explores deeper meaning", "Numbers vs words; reliability vs validity — quantitative is reliable, qualitative gives richer insight"], marks: 2, hint: "Numbers vs descriptions; reliable vs valid" },
    { question: "What is the Marxist explanation of the role of education?", answer: "Marxists (Bowles and Gintis) argue education reproduces class inequality through the hidden curriculum (teaching obedience to authority) and the correspondence principle (school mirrors the workplace), benefiting the ruling class.", acceptedAnswers: ["Education reproduces class inequality through the hidden curriculum and correspondence principle (Bowles and Gintis)", "Marxists argue schools prepare working-class students for obedient labour while benefiting the ruling class — hidden curriculum", "Bowles and Gintis: school mirrors the workplace (correspondence principle) and teaches acceptance of hierarchy to serve capitalism", "Education serves capitalism by reproducing class divisions — hidden curriculum socialises students into accepting inequality"], marks: 2, hint: "Education benefits the ruling class — hidden curriculum, correspondence principle" },
    { question: "What is meant by the 'glass ceiling'?", answer: "The glass ceiling refers to the invisible barrier that prevents women (and other groups) from rising above a certain level in organisations, despite having the qualifications and ability to do so.", acceptedAnswers: ["An invisible barrier preventing women from reaching senior positions despite having the necessary qualifications", "The glass ceiling is an unseen limit on how high women can rise in organisations regardless of their ability", "A metaphor for the informal discrimination that stops women progressing to top management positions", "Hidden barriers that prevent women and minorities from advancing to the highest levels of organisations"], marks: 2, hint: "An invisible barrier stopping women from reaching top positions" },
    { question: "What is a 'reconstituted family'?", answer: "A reconstituted (or blended) family is formed when two adults with children from previous relationships live together as a new family unit. Also called a step-family.", acceptedAnswers: ["A step-family formed from two people with children from previous relationships", "A blended family where one or both partners bring children from a previous relationship", "Reconstituted family = step-family; two adults and children from previous partnerships living together", "A family formed when previously partnered adults with children form a new household together"], marks: 2, hint: "A step-family formed from previous relationships" },
    { question: "What is cohabitation?", answer: "Cohabitation is when an unmarried couple live together in a romantic partnership. It has become increasingly common in the UK as an alternative or precursor to marriage.", acceptedAnswers: ["Living together as a couple without being married", "An unmarried couple sharing a home as if in a marriage relationship", "Cohabitation = couples living together without marrying; increasingly common in modern UK", "When two people live together in a romantic relationship without legal marriage"], marks: 2, hint: "Living together as a couple without being married" },
    { question: "What does Parsons mean by the 'warm bath theory'?", answer: "Parsons argued the family stabilises adult personalities — after the stress of paid work, the family provides emotional relaxation and support, like a warm bath. This is one of the two key functions he identified for the modern nuclear family.", acceptedAnswers: ["The family provides emotional relaxation and support for adults after the stress of work (Parsons)", "Parsons: family is like a warm bath — it soothes and stabilises adult personalities stressed by the workplace", "The family as stress relief for adults — one of Parsons's two key functions alongside primary socialisation", "Family stabilises adult emotions and personalities, just as a warm bath soothes the body — Parsons"], marks: 2, hint: "The family soothes adults after work stress — like a warm bath (Parsons)" },
    { question: "What is the 'dual burden' identified by Ann Oakley?", answer: "The dual burden refers to the situation where women work a double shift — paid employment outside the home plus the majority of domestic labour and childcare inside the home. Oakley argued this reflects gender inequality.", acceptedAnswers: ["Women doing paid work AND most of the domestic work and childcare at home (Oakley)", "The double shift: women work outside the home for pay and then return to unpaid domestic labour", "Dual burden = full-time paid work plus primary responsibility for housework and childcare — Oakley's feminist concept", "Two jobs simultaneously: paid employment plus most of the unpaid domestic and caring work at home"], marks: 2, hint: "Women's double shift: paid work plus most of the housework (Oakley)" },
    { question: "What is a 'self-fulfilling prophecy' in education?", answer: "A self-fulfilling prophecy occurs when a prediction causes itself to become true. In education, if a teacher labels a pupil as 'less able', the pupil may internalise the label and underachieve, fulfilling the original expectation.", acceptedAnswers: ["A prediction that comes true because people act as if it is true — e.g. a teacher's low expectations lead to a pupil underachieving", "When labelling causes someone to behave in line with the label — a teacher expects failure and the student underachieves", "Self-fulfilling prophecy: belief in an outcome (e.g. student will fail) leads to behaviour that makes it happen", "If a teacher believes a pupil will do badly and treats them accordingly, the pupil may fulfil that prediction"], marks: 2, hint: "A prediction becomes true because people act on it — especially in labelling theory" },
    { question: "What is meant by 'anomie'?", answer: "Anomie (Durkheim) is a state of normlessness — when social norms break down or are unclear, individuals feel disconnected from society. Durkheim linked it to higher suicide rates and crime. Merton adapted it to explain crime as a response to blocked goals.", acceptedAnswers: ["Normlessness — a breakdown of social norms causing individuals to feel disconnected (Durkheim)", "Durkheim's concept of normlessness; associated with crime and higher suicide rates", "A state of social disorder where norms are unclear or absent — leads to deviance (Durkheim/Merton)", "Anomie = lack of norms or social rules; Durkheim saw it as dangerous for social cohesion"], marks: 2, hint: "Normlessness — social norms have broken down (Durkheim)" },
    { question: "State two types of family structure other than nuclear.", answer: "Lone-parent family (single parent raising children), reconstituted/blended family (step-family), extended family (grandparents and wider kin), same-sex family (same-sex parents and children), beanpole family (multi-generational but with fewer siblings due to lower birth rates).", acceptedAnswers: ["Lone-parent and reconstituted (step) families", "Extended family and same-sex family", "Single-parent family and beanpole family", "Lone-parent and extended family are two types other than nuclear"], marks: 2, hint: "Think about single parents, step-families, extended families, same-sex families" },
    { question: "What is meant by 'positivism' in sociological research?", answer: "Positivism is the view that sociology should use scientific, objective methods to study society — collecting quantitative data that can be measured, tested, and used to identify patterns and cause-and-effect relationships. Associated with Durkheim.", acceptedAnswers: ["Using scientific methods to study social facts objectively — quantitative data, patterns, laws (Durkheim)", "The belief that sociology should be scientific and objective, using numbers and measurable evidence", "Positivism: society can be studied objectively like natural science — using quantitative data to find patterns", "Scientific approach to sociology — empirical, measurable, objective data (associated with Durkheim)"], marks: 2, hint: "Sociology should be scientific — objective, measurable, quantitative" },
    { question: "What is the difference between 'crime' and 'deviance'?", answer: "Crime is behaviour that breaks the written law of a society and can result in legal punishment. Deviance is behaviour that breaks social norms but may not be illegal — it is defined by social disapproval rather than law.", acceptedAnswers: ["Crime breaks the law and has legal consequences; deviance breaks social norms but may not be illegal", "Crime = illegal behaviour punishable by law; deviance = behaviour that violates social norms but may be legal", "All crime is deviant but not all deviance is criminal — deviance is relative and culturally defined", "Crime involves breaking written laws; deviance involves breaking informal social rules or norms"], marks: 2, hint: "Crime = illegal; deviance = breaking social norms — they overlap but are not the same" },
    { question: "What is Merton's strain theory of crime?", answer: "Merton argued crime results from a strain between culturally valued goals (e.g. wealth) and the legitimate means available to achieve them. Those blocked from legitimate routes may 'innovate' by using illegal means (crime) to achieve the same goals.", acceptedAnswers: ["Strain between society's goals (e.g. wealth) and limited legitimate means to achieve them leads to crime (Merton)", "When people cannot achieve valued goals through legal means, they may turn to crime — Merton's innovation", "Merton: blocked legitimate means + accepted goals = strain that can produce criminal innovation", "Strain theory: society promotes wealth but denies legitimate routes to some people, causing crime"], marks: 2, hint: "Goals valued by society + blocked legitimate means = strain → crime (Merton)" },
    { question: "What is meant by 'formal' and 'informal' social control?", answer: "Formal social control is enforced by official agencies — the police, courts, and prisons — which apply legal sanctions. Informal social control operates through social pressure from family, peers, teachers, and community — using shame, gossip, or exclusion.", acceptedAnswers: ["Formal = police/courts/legal sanctions; informal = family/community pressure, shame, exclusion", "Formal control uses official agencies and law; informal uses social pressure from family and peers", "Police and prisons enforce formal control; family and peers use gossip and shame for informal control", "Official agencies (formal) vs social pressure from peers and family (informal) to enforce conformity"], marks: 2, hint: "Formal = police and law; informal = family and peer pressure" },
    { question: "Who was Howard Becker and what is his key contribution to sociology?", answer: "Howard Becker was an interactionist sociologist who developed labelling theory in 'Outsiders' (1963). He argued deviance is not a quality of the act itself but of the reaction of others — 'deviant is someone who has been successfully labelled as such'.", acceptedAnswers: ["Becker developed labelling theory — deviance is a reaction by others, not a quality of the act", "Becker: 'Outsiders' (1963) — deviance is defined by labelling; moral entrepreneurs create and apply labels", "Interactionist who argued deviance is a social construction based on who gets caught and labelled", "Howard Becker — labelling theory; deviance is not inherent but depends on who is labelled by whom"], marks: 2, hint: "Labelling theory — 'Outsiders' (1963) — deviance is a reaction, not a quality of the act" },
    { question: "What is the difference between 'open' and 'closed' stratification systems?", answer: "A closed stratification system has fixed positions with no movement between strata — e.g. the caste system in traditional India where birth determines rank permanently. An open system, like social class, allows movement between positions through achievement.", acceptedAnswers: ["Closed: fixed positions, no movement (e.g. caste system); open: movement possible through achievement (e.g. class)", "Caste = closed (birth determines status forever); class = open (can move up or down)", "Open systems allow social mobility; closed systems such as the caste system do not", "Closed stratification has rigid hereditary ranks; open stratification permits movement between levels"], marks: 2, hint: "Caste = closed (no movement); class = open (mobility possible)" },
    { question: "What did Durkheim mean by 'social solidarity'?", answer: "Social solidarity is the sense of unity and shared identity that holds society together. Durkheim identified mechanical solidarity (in simple, traditional societies — shared values) and organic solidarity (in complex modern societies — interdependence from the division of labour).", acceptedAnswers: ["Social cohesion and shared identity; Durkheim distinguished mechanical (traditional) and organic (modern) solidarity", "Durkheim: the bonds holding society together — mechanical solidarity in simple societies, organic in complex ones", "Shared unity in society; mechanical = common values in traditional society; organic = interdependence in modern society", "The sense of belonging and shared identity in a society — essential for social cohesion (Durkheim)"], marks: 2, hint: "The glue holding society together — Durkheim's mechanical vs organic solidarity" },
    { question: "What is 'participant observation' as a research method?", answer: "Participant observation is where the researcher joins the group being studied, either openly (overt) or secretly (covert). It produces rich, valid qualitative data but raises ethical issues, is time-consuming, and the researcher may lose objectivity (going native).", acceptedAnswers: ["The researcher joins the group being studied — overt (known) or covert (secret); produces valid qualitative data", "Participant observation: researcher becomes a member of the group studied; high validity but risks losing objectivity", "Overt or covert involvement in a group to study it from inside; rich data but ethical issues arise", "Joining a group to observe it from within — produces valid data but risks researcher bias and ethical problems"], marks: 2, hint: "The researcher joins the group — overt or covert; high validity, ethical concerns" },
    { question: "What is 'cultural capital' and who developed the concept?", answer: "Cultural capital is the knowledge, attitudes, language style (elaborated code), and social skills that middle-class families possess and pass to their children. Schools reward these attributes, giving middle-class children a structural advantage. Developed by Pierre Bourdieu.", acceptedAnswers: ["Bourdieu: middle-class attitudes, language and knowledge valued by schools, giving structural advantage to their children", "Cultural capital = middle-class values and elaborated code that schools reward — concept from Bourdieu", "The non-financial social assets (knowledge, language, manners) that help people succeed — developed by Bourdieu", "Knowledge and language styles of the middle class that provide advantage in education — Bourdieu's concept"], marks: 2, hint: "Middle-class knowledge and language that schools reward — Bourdieu" },
    { question: "What is meant by the 'gender pay gap'?", answer: "The gender pay gap is the average difference in pay between male and female workers. In the UK it is approximately 14–18%. It is partly explained by vertical segregation (women less likely to hold senior roles), horizontal segregation (women concentrated in lower-paid sectors), and the dual burden.", acceptedAnswers: ["Average difference in earnings between men and women; approximately 14–18% in the UK", "Women earn less than men on average; caused by glass ceiling, horizontal segregation and dual burden", "The gap in average pay between male and female workers — around 14-18% in the UK", "Men earn more than women on average; explained by occupational segregation and caring responsibilities"], marks: 2, hint: "Average earnings difference between men and women — around 14-18% in the UK" },
    { question: "What is 'secondary socialisation'?", answer: "Secondary socialisation is the process of learning norms and values outside the family — through school, peer groups, media, religion, and the workplace. It continues throughout life and reinforces or adds to primary socialisation.", acceptedAnswers: ["Learning norms and values through school, peer groups, media and religion — outside the family", "Secondary socialisation occurs through agents outside the family such as school, media and peers", "Socialisation that happens after primary socialisation — school, peers, media, religion, work", "The continuation of socialisation beyond the family, through school and other secondary agencies"], marks: 2, hint: "Socialisation outside the family — school, peers, media, religion" },
    { question: "What is meant by 'reliability' in sociological research?", answer: "Reliability means a research method produces consistent results when repeated — another researcher using the same method would get the same findings. Quantitative methods such as structured questionnaires tend to be more reliable.", acceptedAnswers: ["Research that produces the same results when repeated — quantitative methods tend to be more reliable", "Reliability: consistent results if the study is replicated by another researcher", "A reliable study gives the same results when repeated in the same way; linked to quantitative methods", "Consistency of findings — if a study can be replicated with the same results it is reliable"], marks: 2, hint: "Consistent results when the research is repeated" },
    { question: "What is 'validity' in sociological research?", answer: "Validity means research actually measures what it claims to measure and reflects true social reality. Qualitative methods such as unstructured interviews tend to have higher validity because they capture real attitudes and meanings in depth.", acceptedAnswers: ["Research that measures what it claims to and reflects true social reality — qualitative methods are more valid", "Validity: the research accurately captures the truth of social life rather than an artificial or surface picture", "A valid study truly represents the reality being studied; qualitative methods tend to be more valid than quantitative", "Research is valid if it measures what it intends to — depth of qualitative data improves validity"], marks: 2, hint: "Does the research truly measure what it claims to? Linked to qualitative methods" },
    { question: "What is the difference between 'overt' and 'covert' observation?", answer: "In overt observation the researcher is open about their role — the group knows they are being studied. In covert observation the researcher's identity is hidden. Covert produces more natural behaviour but raises ethical issues around deception and consent.", acceptedAnswers: ["Overt: group knows they are being studied; covert: the researcher's identity is hidden", "Overt = open and known to participants; covert = secret — raises ethical issues of deception", "Overt observation: researcher known to group. Covert: researcher conceals role and identity", "Open (overt) vs hidden (covert) observation; covert gives more natural data but is ethically problematic"], marks: 2, hint: "Overt = researcher known; covert = researcher hidden and secret" },
    { question: "What is meant by 'official statistics' in sociological research?", answer: "Official statistics are quantitative data collected by government agencies (e.g. census, crime statistics, unemployment figures). They are cheap, large-scale, and allow trends over time to be tracked, but may reflect recording practices and political priorities rather than social reality.", acceptedAnswers: ["Quantitative data collected by government — e.g. census, crime figures; cheap and large-scale but may lack validity", "Government-produced numerical data such as the census or official crime statistics", "Official statistics: government data sets; allow comparison over time but may under-represent hidden crimes or groups", "Numbers produced by state bodies — useful for trends but affected by recording practices and under-reporting"], marks: 2, hint: "Government-collected quantitative data — census, crime figures" },
    { question: "What is 'ethnic minority' and what does 'ethnocentrism' mean?", answer: "An ethnic minority is a group that differs in culture, language, or religion from the dominant group in a society. Ethnocentrism is judging other cultures by the standards of one's own culture, assuming one's own culture is superior.", acceptedAnswers: ["Ethnic minority: a cultural/linguistic/religious group smaller than the dominant group; ethnocentrism: judging others by your own culture's standards", "Ethnocentrism = assuming your own culture is the norm and judging others negatively by it", "An ethnic minority differs from the majority group; ethnocentrism is seeing the world from only one's own cultural perspective", "Ethnic minority: group with distinct culture from the majority; ethnocentrism: viewing other cultures as inferior to your own"], marks: 2, hint: "Ethnic minority differs from the majority; ethnocentrism judges others by your own cultural standards" },
    { question: "What is 'social stratification'?", answer: "Social stratification is the division of society into hierarchical layers or strata based on factors such as class, wealth, status, and power. Examples of stratification systems include the caste system, feudal system, and class system.", acceptedAnswers: ["The division of society into hierarchical layers based on class, wealth, status or power", "A hierarchy of social groups with unequal access to wealth, status and power — e.g. class or caste", "Social stratification: society ranked into tiers with different levels of wealth and power", "The layering of society into groups with unequal resources and opportunities"], marks: 2, hint: "Society divided into ranked layers — class, caste, wealth, status" },
    { question: "What is meant by 'moral panic' (Cohen)?", answer: "A moral panic is a disproportionate public concern about a perceived social threat, amplified by sensationalised media coverage. The identified group becomes a 'folk devil'. Associated with Stanley Cohen's study of mods and rockers in the 1960s.", acceptedAnswers: ["Disproportionate public anxiety about a perceived social threat, amplified by the media — Cohen studied mods and rockers", "Cohen: media creates exaggerated fears about a group ('folk devil'), causing a moral panic", "Moral panic: media-amplified overreaction to a group seen as a threat to social values", "Exaggerated societal concern about a group perceived as dangerous — Stanley Cohen's concept"], marks: 2, hint: "Exaggerated public concern about a threat, amplified by media — Cohen's folk devils" },
    { question: "What is Davis and Moore's functionalist view of social stratification?", answer: "Davis and Moore (1945) argued that social inequality is a functional necessity — high rewards (pay, status) attract the most talented people to the most important and demanding roles in society, ensuring these positions are filled by the most able.", acceptedAnswers: ["Inequality is functional: high rewards attract the most talented to the most important roles (Davis and Moore)", "Davis and Moore: stratification motivates the most able to take on the most demanding roles — inequality is necessary", "Social inequality motivates talented individuals to work hard and fill important positions — functional necessity", "High pay and status in important jobs ensures society's key roles are filled by the most talented people"], marks: 2, hint: "Inequality motivates the most talented to fill the most important roles — Davis and Moore" },
    { question: "What is an 'unstructured interview' in sociological research?", answer: "An unstructured interview is a flexible, conversational research method where the researcher has no set questions — topics emerge from the conversation. It produces rich, valid qualitative data but is time-consuming and difficult to compare across respondents.", acceptedAnswers: ["A flexible conversation with no set questions — produces rich qualitative data but is hard to compare", "Unstructured interview: researcher and respondent talk freely with no fixed questions; high validity but low reliability", "No pre-set questions; the interview follows the respondent's lead — valid, in-depth but not reliable", "A conversational interview with no fixed question order; produces detailed qualitative data"], marks: 2, hint: "No set questions — open conversation; rich qualitative data but hard to compare" },
    { question: "What is 'Weberian' stratification?", answer: "Max Weber argued stratification has three dimensions: class (economic position), status (social prestige/respect), and party (political power). These do not always overlap — someone can have high status but low income (e.g. a vicar) or high income but low status (e.g. a drug dealer).", acceptedAnswers: ["Weber: three dimensions of stratification — class (economic), status (prestige), party (power)", "Weber argued class, status and party are separate but related dimensions of inequality", "Weberian stratification: income/wealth, social prestige, and political power as distinct but overlapping hierarchies", "Weber distinguished economic class, social status, and political power as three separate dimensions of inequality"], marks: 2, hint: "Three dimensions — class (money), status (prestige), party (power) — they can diverge" },
    { question: "What is the 'correspondence principle' (Bowles and Gintis)?", answer: "The correspondence principle holds that the social relationships in school mirror (correspond to) those in the workplace. Hierarchy, obedience, external rewards, and lack of control over work in school prepare pupils for the same conditions as employees, reproducing capitalism.", acceptedAnswers: ["School mirrors the workplace — hierarchy and obedience in school correspond to employment relationships (Bowles and Gintis)", "The way school is organised corresponds to the factory floor — preparing students for obedient work (Bowles and Gintis)", "Bowles and Gintis: school reproduces workplace relations through the correspondence principle — hierarchy and deference", "School relations (teacher authority, grades for effort) correspond to work relations (boss, wages) — Bowles and Gintis"], marks: 2, hint: "School mirrors the workplace — hierarchy and compliance (Bowles and Gintis)" },
    { question: "What is 'horizontal occupational segregation'?", answer: "Horizontal segregation describes the tendency for men and women to work in different occupational sectors. Women are concentrated in caring, cleaning, catering, and clerical work (the 'five Cs') which are lower paid; men dominate in construction, engineering, and finance.", acceptedAnswers: ["Men and women concentrated in different sectors — women in caring/clerical (lower paid), men in construction/finance", "Horizontal segregation: different jobs for men and women across different industries", "Women cluster in the 'five Cs' (caring, cleaning, catering, clerical, cashiering); men in engineering and construction", "Gender-based division across occupational sectors — lower-paid sectors dominated by women"], marks: 2, hint: "Men and women in different sectors — women in caring/'five Cs', men in engineering/finance" },
    { question: "What is 'vertical occupational segregation'?", answer: "Vertical segregation refers to the unequal distribution of men and women at different levels within the same occupation or organisation. Men disproportionately occupy senior positions; women are concentrated at lower levels. The glass ceiling prevents upward movement.", acceptedAnswers: ["Men hold senior positions; women concentrated at lower levels within the same organisation or profession", "Vertical segregation: men dominate the top of hierarchies; women hit the glass ceiling", "Unequal distribution of men and women across levels of seniority — glass ceiling prevents women rising", "Women concentrated at lower grades and men at higher grades in the same sector — vertical segregation"], marks: 2, hint: "Within the same sector, men are at the top and women are at the bottom — glass ceiling" },
    { question: "What did Ann Oakley conclude about domestic labour?", answer: "Ann Oakley (1974) found in her study of housewives that domestic labour is real, skilled work but is socially devalued because it is unpaid and performed by women. She challenged the functionalist view that domestic roles are natural, arguing they are socially constructed.", acceptedAnswers: ["Oakley: domestic labour is real work but devalued because it is unpaid and done by women", "Oakley challenged the idea that women's domestic role is natural — it is socially constructed and undervalued", "Domestic work is skilled but unpaid and devalued because society associates it with women (Oakley 1974)", "Oakley argued housework is work but undervalued; women's domestic role is socially constructed not biologically determined"], marks: 2, hint: "Domestic labour is real work but devalued because it is unpaid and done by women — Oakley" },
    { question: "What is meant by a 'lone-parent family'?", answer: "A lone-parent family consists of one parent living with their dependent children without a partner. In the UK, around 90% of lone-parent families are headed by women. Lone parenthood has increased due to rising divorce rates, cohabitation breakdown, and changing attitudes.", acceptedAnswers: ["One parent living with dependent children, without a partner — over 90% headed by women in the UK", "A single-parent family; one adult raising children without a co-resident partner", "Lone-parent family: one parent and their children — increasingly common due to divorce and changing norms", "A single parent household — usually mother-headed; caused by divorce, separation or choice"], marks: 2, hint: "One parent raising children — usually the mother in the UK" },
    { question: "What is Durkheim's view on the function of crime?", answer: "Durkheim argued crime is functional for society: it reinforces social norms and boundaries (the criminal's punishment clarifies what is unacceptable), generates social solidarity (society unites against the criminal), and can facilitate social change (today's deviance is tomorrow's norm).", acceptedAnswers: ["Crime is functional — it reinforces norms, creates solidarity, and can drive social change (Durkheim)", "Durkheim: crime clarifies norms, unites society against wrongdoing, and allows gradual social change", "Crime has positive functions: it defines boundaries of acceptable behaviour and brings society together against it", "Durkheim: some crime is inevitable and functional — reinforces norms and can signal need for social change"], marks: 2, hint: "Crime is functional — reinforces norms, creates solidarity, enables social change (Durkheim)" },
    { question: "What is 'interpretivism' in sociological research?", answer: "Interpretivism holds that social reality is constructed through meanings, and sociology must understand the subjective experiences and motivations of individuals. It favours qualitative methods (unstructured interviews, observation) that explore meaning rather than measure behaviour.", acceptedAnswers: ["Sociology should understand people's subjective meanings and experiences; favours qualitative methods", "Interpretivist approach: focus on individual meaning and understanding, not objective measurement", "Interpretivism: social reality is constructed by individuals; must be understood from their perspective; uses qualitative methods", "Understanding the subjective meanings people give to social life — interpretivist sociologists reject positivism"], marks: 2, hint: "Understand subjective meaning — qualitative methods; contrasts with positivism" },
  ],
  mid: [
    { question: "Explain how the family performs functions for society, according to functionalists.", answer: "Functionalists see the family as essential to social stability. Murdock (1949) identified four universal functions: sexual (regulating sexual activity), reproductive (producing the next generation), economic (providing for members), and educational (primary socialisation). Parsons added two modern functions: stabilisation of adult personalities (the family as 'warm bath') and socialisation of children. Critics argue this ignores family dysfunction, domestic violence, and gender inequality.", acceptedAnswers: ["Murdock: four functions — sexual, reproductive, economic, educational. Parsons adds personality stabilisation and socialisation", "Functionalists see family as performing primary socialisation, economic support, reproduction and emotional stabilisation", "Murdock's four functions plus Parsons's 'warm bath' theory — family provides stability for adults and socialises children", "Family performs socialisation, regulates reproduction, provides economic support — functionalists see it as essential for social order"], marks: 4, hint: "Name Murdock and Parsons, list specific functions, briefly note a criticism" },
    { question: "Explain what sociologists mean by the 'hidden curriculum' and how it reproduces inequality.", answer: "The hidden curriculum refers to informal lessons taught in school beyond the formal academic content — attitudes like punctuality, obedience, and conformity. Marxists Bowles and Gintis argue it reproduces ruling-class values, preparing working-class students for obedient labour and middle-class students for authority. This makes class inequality appear natural and inevitable across generations.", acceptedAnswers: ["Hidden curriculum = informal learning (obedience, conformity) that Bowles and Gintis argue reproduces class inequality", "Beyond formal lessons, schools teach values like punctuality and deference that benefit capitalism (Bowles and Gintis)", "The hidden curriculum teaches students to accept hierarchy — this serves the ruling class by producing compliant workers", "Unwritten lessons in schools about conformity and authority that reproduce the class structure across generations"], marks: 4, hint: "Define hidden curriculum, link to Bowles and Gintis, explain how it serves capitalism" },
    { question: "Outline and explain two reasons why educational achievement differs between social classes.", answer: "1. Material deprivation: working-class families may lack money for books, internet access, tutors, and quiet study space. Poverty-related stress and poor diet affect concentration and attendance. 2. Cultural capital (Bourdieu): middle-class families possess the attitudes, language (elaborated code — Bernstein), and social networks valued by schools. They navigate the education system more effectively, giving their children a structural advantage unrelated to ability.", acceptedAnswers: ["Material deprivation (lack of resources) and cultural capital (Bourdieu — middle-class values and language advantage)", "Working-class pupils face material poverty and lack cultural capital — the elaborated code and attitudes schools reward", "1. Material: no money for revision resources. 2. Cultural capital: middle-class families have knowledge and networks that help their children", "Bernstein's elaborated vs restricted code, and material deprivation, both disadvantage working-class students in education"], marks: 4, hint: "Cover material deprivation (money/resources) and cultural capital (values/language/social networks)" },
    { question: "Explain two ways in which sociologists study crime and deviance.", answer: "1. Official statistics: police-recorded crime data. Cheap and large-scale but affected by under-reporting, police discretion, and recording practices — creating the 'dark figure' of crime. 2. Victim surveys (e.g. Crime Survey for England and Wales): ask people about crimes committed against them regardless of reporting. More accurate picture but still miss crimes against organisations or victimless crimes. Both methods have validity issues because crime itself is a social construction — defined differently across cultures and times.", acceptedAnswers: ["Official statistics (cheap, large-scale, but underestimates real crime) and victim surveys (more accurate but miss victimless crime)", "Police records and victim surveys are two methods — both have limitations including the dark figure and non-recording of all crime", "Official crime data and self-report/victim surveys; official data misses unreported crime; surveys miss crimes with no individual victim", "Two methods: official statistics (limited by under-reporting) and victim surveys like the CSEW (more complete but still imperfect)"], marks: 4, hint: "Name two specific methods, explain how they work, and state a strength and weakness of each" },
    { question: "Evaluate the view that gender inequalities in employment are declining.", answer: "Evidence of decline: Equal Pay Act (1970), Sex Discrimination Act (1975), more women in higher education (women now outperform men at degree level). Women in senior roles has increased. Evidence of continued inequality: gender pay gap remains (~18% in UK); vertical segregation (few women in senior positions — glass ceiling); horizontal segregation (women concentrated in lower-paid sectors — caring, retail). Oakley argues domestic responsibilities (dual burden) limit women's careers. Walby's theory of patriarchy: gender inequality is systemic, not incidental. Overall: inequalities persist despite legal progress.", acceptedAnswers: ["Progress made (Equal Pay Act, more women graduates) but pay gap, glass ceiling and dual burden persist — inequality continues", "Legal reforms improved things but vertical/horizontal segregation and the ~18% pay gap show inequalities remain", "Gender pay gap and glass ceiling show ongoing inequality despite legislative progress; Walby argues patriarchy is systemic", "Women outperform men in education but face glass ceiling, pay gap and dual burden — inequality is declining slowly"], marks: 4, hint: "Give evidence on both sides — progress made AND continuing inequality. Include specific concepts (glass ceiling, pay gap, dual burden)" },
    { question: "Explain what sociologists mean by 'secularisation' and give evidence for and against the view that Britain is becoming more secular.", answer: "Secularisation refers to the declining social significance of religion. Evidence for: church attendance in Britain has fallen sharply (from ~40% in 1900 to ~5% today); fewer people identify as Christian in census data; religious institutions have less influence on law and government. Evidence against: religious diversity has increased (Islam, Hinduism growing); belief without belonging (Davie) — people still hold private beliefs; religious organisations still provide welfare and community. Religion may be changing form rather than declining.", acceptedAnswers: ["For secularisation: falling church attendance, less religious identity. Against: Davie's 'believing without belonging', growing non-Christian faiths", "Church attendance has fallen dramatically but Davie argues private belief persists — Britain may be restructuring rather than secularising", "Evidence for: 5% church attendance. Evidence against: growing Islam and Hinduism, private belief remaining (Davie)", "Secularisation debate: attendance/membership down but religious diversity growing — religion may be changing not disappearing"], marks: 4, hint: "Define secularisation, then give stats and examples on both sides" },
    { question: "Outline and explain two ways in which ethnicity affects educational achievement in Britain.", answer: "1. Racism and teacher expectations: black Caribbean pupils, particularly boys, are more likely to be placed in lower sets (streaming/labelling — Gillborn) and excluded from school at disproportionate rates. Teacher labelling can create a self-fulfilling prophecy of underachievement. 2. Material deprivation: many Black and minority ethnic families face poverty due to structural racism in employment. Overcrowded housing, inability to fund tutoring, and stress all reduce attainment. Note: Chinese and Indian heritage students outperform the national average — suggesting cultural factors such as family emphasis on education also matter.", acceptedAnswers: ["Racism and labelling (Gillborn) and material deprivation both disadvantage some ethnic minority students; but Chinese/Indian students outperform average", "Teacher expectations and structural racism in employment (material deprivation) affect achievement — though patterns vary by ethnic group", "1. Labelling/racism: Black Caribbean boys disproportionately excluded. 2. Material poverty due to employment discrimination", "Gillborn's research on labelling, plus material deprivation from structural racism — but not all ethnic groups underachieve"], marks: 4, hint: "Cover labelling/racism and material deprivation. Acknowledge variation between ethnic groups." },
    { question: "Explain two reasons why Marxists argue that media content reflects the interests of the ruling class.", answer: "1. Ownership and control: major media outlets are owned by a small number of powerful conglomerates (e.g. Rupert Murdoch's News Corp). Owners can directly or indirectly shape editorial content to promote their economic interests and political views. 2. Advertising dependency: media outlets rely on advertising revenue from large corporations. Critical coverage of corporate power may be avoided to protect advertising income. Marxists (Glasgow Media Group — 'Bad News') found that industrial disputes were systematically reported from an employer's perspective.", acceptedAnswers: ["Media ownership by ruling-class conglomerates and advertising dependency both lead to content that serves the powerful", "Murdoch's ownership example shows how owners shape content; advertising revenue creates further corporate influence over media", "1. Concentrated ownership (e.g. News Corp) lets owners promote ruling-class interests. 2. Ad revenue dependency discourages critical coverage of corporations", "Glasgow Media Group: media ownership and advertising dependency mean coverage favours corporate/ruling-class perspectives"], marks: 4, hint: "Cover media ownership concentration and advertising dependency — link both to ruling-class ideology" },
    { question: "Describe and evaluate the feminist perspective on the family.", answer: "Feminists argue the family is a key site of gender oppression. Liberal feminists highlight unequal division of domestic labour (the 'dual burden' — Oakley) and campaigned for legal reforms. Radical feminists (Delphy and Leonard) see the family as a patriarchal institution where women's unpaid labour is exploited by men. Marxist feminists link women's domestic role to capitalism — reproducing the labour force for free. Evidence: surveys consistently show women perform more domestic work even when employed full-time. Evaluation: ignores diversity of family types; some women do experience the family as a source of support and fulfilment. Postmodern feminists argue family is negotiated differently for different women.", acceptedAnswers: ["Feminists critique family as a site of patriarchy (radical), legal inequality (liberal), and capitalism's exploitation of domestic labour (Marxist feminist)", "Oakley's dual burden, Delphy and Leonard's patriarchy critique, and Marxist feminism all see the family as oppressive to women", "Three feminist views: liberal (legal reform), radical (patriarchy), Marxist feminist (capitalism). Criticisms: ignores diverse family experiences", "Feminist perspectives see family as oppressive; Oakley's dual burden evidence supports this; postmodernists argue experiences vary"], marks: 6, hint: "Cover liberal, radical, and Marxist feminist views. Use Oakley and Delphy. Evaluate with counter-arguments." },
    { question: "Explain what is meant by 'relative poverty' and discuss whether poverty in Britain is mainly the fault of the poor themselves.", answer: "Relative poverty means having significantly less than the average standard of living in society. In Britain, the poverty line is often set at below 60% of median income. 'Culture of poverty' explanation (Murray's underclass thesis): some argue persistent poverty is caused by a welfare dependency culture where people lack ambition and choose benefits over work. Structural explanations: Marxists and sociologists argue poverty is caused by systemic inequality — low wages, job insecurity, high housing costs, poor school funding in deprived areas. Evidence supports structural view: poverty increases during recessions and austerity regardless of individual behaviour. Social mobility in UK is lower than many comparable countries. Conclusion: blaming the poor ignores the role of structural inequalities.", acceptedAnswers: ["Relative poverty = below 60% median income; Murray's underclass blames individuals; Marxists blame structural inequality — evidence favours structural view", "Culture of poverty (Murray) vs structural inequality — recessions and low social mobility suggest structure rather than individual failure causes poverty", "Underclass thesis argues welfare dependency; sociologists counter that low wages, housing costs and inequality cause poverty structurally", "Poverty is better explained by structural factors (inequality, housing, wages) than individual fault — social mobility data supports this"], marks: 6, hint: "Define relative poverty, then present both individual (culture of poverty) and structural explanations, and evaluate each" },
    { question: "Explain what is meant by labelling theory and evaluate its usefulness for understanding crime and deviance.", answer: "Labelling theory (Becker, 1963) argues deviance is not a quality of an act but of how society reacts to it. Being labelled 'criminal' or 'deviant' by authorities can lead to a deviant career as the labelled person internalises the identity (master status) and joins deviant subcultures. Strengths: explains why not all rule-breaking is treated equally — e.g. middle-class drug users vs working-class offenders. Explains secondary deviance (Lemert). Weaknesses: ignores primary deviance (the initial act); deterministic — not everyone labelled becomes a career criminal. Marxists argue labelling ignores why the powerful define what is deviant in the first place.", acceptedAnswers: ["Becker: deviance is a label applied by others; leads to deviant career and master status; but ignores primary deviance", "Labelling creates self-fulfilling prophecy and deviant career; useful but ignores why some acts are labelled and others not", "Strengths: explains unequal enforcement and secondary deviance. Weaknesses: deterministic, ignores initial causes of deviance", "Labelling theory: deviance socially constructed by reaction; useful but ignores structural causes and is deterministic"], marks: 6, hint: "Explain the theory (Becker, master status, deviant career), then give strengths and weaknesses with theorists" },
    { question: "Explain Merton's strain theory and evaluate how well it explains crime in contemporary society.", answer: "Merton (1938) argued American society promotes wealth as a universal goal but provides unequal access to legitimate means. Those blocked from legitimate routes experience 'strain' and may respond by: conformity, innovation (crime), ritualism, retreatism (withdrawal), or rebellion. Strengths: explains why working-class crime rates are higher — legitimate means are more blocked. Links crime to structural inequality rather than individual failing. Weaknesses: struggles to explain white-collar crime (the wealthy also commit crimes despite having access). Does not explain non-economic crime (violence, vandalism). Cultural rather than structural — assumes everyone values wealth equally. Subcultural theories (Cohen, Cloward and Ohlin) develop it further.", acceptedAnswers: ["Merton: strain between goals and means causes crime; explains working-class crime rates but not white-collar or non-economic crime", "Strain theory links crime to blocked opportunities; useful for explaining class differences in crime but not crime by the wealthy", "Five responses to strain (conformity to rebellion); structural focus is useful; weaknesses include ignoring corporate crime", "Merton explains deprived groups turning to crime; doesn't explain why wealthy people commit crime; subcultural theories extend it"], marks: 6, hint: "Explain five responses to strain, give two strengths and two weaknesses. Mention white-collar crime as a problem for the theory." },
    { question: "Explain the sociological evidence for and against the view that the family is becoming more equal in contemporary Britain.", answer: "Evidence for greater equality: Willmott and Young's 'symmetrical family' (1973) — men increasingly participating in domestic work and childcare. More women in paid work, dual-income households becoming the norm. Legal changes: Equality Act, shared parental leave. Joint decision-making more common. Evidence against: Oakley's dual burden still applies — women still do more housework even in dual-income households. Time-use surveys confirm the domestic division of labour remains unequal. Glass ceiling and pay gap show wider gender inequality continues. Ann Oakley (1974): domestic roles are socially constructed and resistant to change. Conclusion: some movement toward equality in domestic life but full equality has not been achieved.", acceptedAnswers: ["Evidence for: symmetrical family, legal reforms, dual-income households. Against: dual burden, time-use surveys, Oakley's findings", "Willmott and Young's symmetrical family vs Oakley's dual burden — some change but women still do more at home", "More equal on paper (legislation, shared leave) but in practice women still do more domestic work — studies confirm this", "Movement toward equality but Oakley and time-use surveys show domestic labour remains unequal"], marks: 6, hint: "Use Willmott and Young (for) and Oakley and time-use surveys (against). Give a clear conclusion." },
    { question: "Explain what positivists mean by 'reliability' and what interpretivists mean by 'validity', and explain why there is a tension between these two goals in sociological research.", answer: "Reliability (positivist): research produces consistent, replicable results — another researcher using the same method gets the same findings. Structured questionnaires and official statistics score well. Validity (interpretivist): research genuinely captures social reality and measures what it claims to. Unstructured interviews, participant observation score better because they capture depth and real meanings. The tension: methods that maximise reliability (standardised, formal) tend to produce artificial or surface-level data — reducing validity. Methods that maximise validity (open, flexible) are difficult to replicate — reducing reliability. Sociologists must choose or balance both depending on their research question and ontological position.", acceptedAnswers: ["Reliability = consistent, replicable results; validity = genuine capture of social reality; there is a trade-off between them", "Structured methods are reliable but less valid; unstructured methods more valid but less reliable — a fundamental tension", "Positivists prioritise reliability; interpretivists prioritise validity; standardised methods sacrifice depth for consistency", "Questionnaires are reliable but may miss real meanings; observation is valid but can't be replicated — the reliability-validity trade-off"], marks: 6, hint: "Define both concepts clearly, explain what methods achieve each, then explain the trade-off between them" },
    { question: "Explain two ways in which social class affects an individual's life chances.", answer: "1. Health: working-class individuals have lower life expectancy, higher rates of chronic illness and mental health problems. The Black Report (1980) and Acheson Report (1998) found persistent health inequalities linked to material deprivation (poor housing, diet, work conditions) not lifestyle choice. 2. Education: working-class pupils underachieve relative to middle-class peers due to material deprivation and cultural capital differences (Bourdieu). Private schooling gives upper-class pupils access to elite universities and professions — ~7% of pupils in private schools account for ~40% of Russell Group students. Both show that class origins powerfully shape life outcomes independent of individual ability.", acceptedAnswers: ["Health (Black Report: lower life expectancy for working class) and education (cultural capital, private schooling) both show class shapes life chances", "Working-class disadvantage in health and education — material deprivation and cultural capital both operate", "1. Health inequalities (Black Report — poor housing, diet). 2. Educational underachievement (cultural capital, material deprivation)", "Life chances affected by class via health outcomes and educational attainment — both linked to material and cultural inequality"], marks: 4, hint: "Choose two areas (health, education, work, crime...) and use specific evidence for each" },
    { question: "Explain what sociologists mean by a 'deviant career' and how labelling theory accounts for it.", answer: "A deviant career (Becker) describes the process by which an individual who is labelled deviant moves progressively further into deviant identity and behaviour. Initially labelled for a primary act of deviance (Lemert), the label becomes a 'master status' that overrides all other identities. Others treat the person as deviant; legitimate opportunities close; the person joins deviant subcultures for support, which reinforces deviant behaviour. Secondary deviance (Lemert) is the result — continued rule-breaking as a response to the label itself.", acceptedAnswers: ["Deviant career: labelling creates master status, closes legitimate opportunities, leads to secondary deviance and subculture membership", "Becker's concept: once labelled, person adopts deviant identity as master status and career in deviance follows", "Primary deviance → labelling → master status → secondary deviance → deviant career — Becker and Lemert", "Labelling leads to a deviant career by closing legitimate routes and pushing labelled persons into deviant groups"], marks: 4, hint: "Explain primary deviance, master status, secondary deviance (Lemert) and how subcultures reinforce the label" },
    { question: "Explain the advantages and disadvantages of using participant observation to study deviant groups.", answer: "Advantages: high validity — the researcher sees behaviour as it naturally occurs, not what people say they do. Access to information respondents would not share in a questionnaire. Detailed, rich data allows understanding of meanings and motivations. Key study: Whyte's 'Street Corner Society' (1943). Disadvantages: ethical issues — covert observation involves deception and no informed consent. Going native — researcher may over-identify with the group and lose objectivity. Danger (particularly with criminal groups). Small sample — findings are not generalisable. Time-consuming. Hawthorne effect: if overt, participants may change behaviour. The method's validity advantage must be weighed against serious ethical and practical limitations.", acceptedAnswers: ["Advantages: high validity, natural behaviour, rich data. Disadvantages: ethics (deception), going native, danger, small sample, not generalisable", "Participant observation gives valid insight but raises ethical issues (covert deception) and risks researcher bias", "Strengths: genuine insight into deviant behaviour. Weaknesses: ethical problems, Hawthorne effect, not representative", "Rich valid qualitative data; problems include deception, loss of objectivity, danger, and small non-representative samples"], marks: 4, hint: "Give at least two advantages and two disadvantages — include the ethical issue and the problem of going native" },
    { question: "Explain what sociologists mean by 'social control' and give examples of both formal and informal social control.", answer: "Social control refers to the mechanisms by which society encourages conformity to norms and punishes deviance. Formal social control is exercised by official agencies: police (arrest and charge), courts (trial and sentence), prisons (punishment and deterrence), mental health institutions (involuntary detention). Informal social control operates through socialisation: family (shame and reward), peer groups (exclusion, gossip), religion (moral guidance), media (stigmatisation of deviance). Both work together — most people conform without ever encountering formal control because informal socialisation has internalised norms.", acceptedAnswers: ["Formal: police, courts, prisons. Informal: family, peers, religion, media — both enforce conformity to social norms", "Social control maintains order; formal = legal sanctions; informal = socialisation through family, peers, religion", "Mechanisms of social control: formal (criminal justice system) and informal (family shame, peer pressure, religious teaching)", "Formal control (police, prisons) and informal control (gossip, family, peer exclusion) both encourage conformity"], marks: 4, hint: "Define social control, then give two examples of formal and two of informal mechanisms" },
    { question: "Explain two reasons why there is a gender gap in recorded crime statistics.", answer: "1. Socialisation: boys are socialised into hegemonic masculinity — risk-taking, toughness, and rejection of authority — making them more likely to commit crime. Girls are socialised into conformity, emotional expression, and caring roles. 2. The 'chivalry thesis' (Pollak): the criminal justice system treats women more leniently — police are less likely to arrest, prosecutors less likely to charge, and courts less likely to convict women for similar offences, making the female crime rate appear artificially low. Both factors may explain the gap without meaning that women commit no crime.", acceptedAnswers: ["Socialisation into masculinity increases male crime; chivalry thesis (Pollak) suggests women treated more leniently in CJS", "Hegemonic masculinity leads to male risk-taking and crime; women's leniency in the criminal justice system reduces recorded female crime", "1. Gender socialisation differences (masculinity/risk). 2. Chivalry thesis — women treated more leniently by police and courts", "Boys socialised into rule-breaking; women under-represented in statistics due to chivalry or underreporting of female crime"], marks: 4, hint: "Cover gender socialisation (masculinity) and the chivalry thesis — explain each fully" },
    { question: "Explain what sociologists mean by the 'symmetrical family' and evaluate how accurate this concept is today.", answer: "Willmott and Young (1973) argued the modern family is increasingly 'symmetrical' — roles between husbands and wives are becoming more equal, with men participating more in domestic work and childcare and women increasingly in paid work. Evidence for: dual-income households are now the norm; men do more childcare than in previous generations; shared parental leave exists. Evidence against: Oakley's research shows women still do significantly more housework. Time-use surveys consistently confirm the dual burden. The gender pay gap persists. Feminist sociologists argue the symmetrical family is a myth that conceals enduring inequality. Conclusion: some trend toward symmetry exists but the family is not yet truly equal.", acceptedAnswers: ["Symmetrical family (Willmott and Young): increasingly equal roles; challenged by Oakley's dual burden and time-use data", "Willmott and Young see growing equality; Oakley and time-use surveys show women still do more — symmetry is partial at best", "Symmetrical family describes increased male participation; in practice women still shoulder more domestic responsibility", "Some movement toward equality (dual income, shared leave) but full symmetry contradicted by persistent dual burden evidence"], marks: 6, hint: "Define symmetrical family (Willmott and Young), give evidence for, then evaluate using Oakley and time-use surveys" },
  ],
  long: [
    { question: "'The media is the most powerful agent of socialisation in contemporary society.' Discuss this view. (20 marks)", answer: "Media's growing influence: Postmodernists (Baudrillard) suggest media creates 'hyperreality' — people construct identities from media representations. Average UK teenager spends 7+ hours per day on screens. Social media shapes gender norms, body image, political views, and consumer behaviour. Neo-Marxists (Glasgow Media Group) argue media transmits ruling-class ideology. Against: the family remains the primary agent — shapes fundamental values and language in the first years of life; Parsons's 'warm bath' function. Education provides sustained, formal socialisation over 13+ years. Peer groups are especially powerful in adolescence (Hargreaves). Religion remains significant for many ethnic/religious communities. Evaluation: media's influence is growing — particularly social media for identity formation — but relative importance varies by class, age, and media literacy. Interactionist view: audiences are not passive (uses and gratifications theory). Multiple agents interact throughout the life course. Conclusion: the family remains foundational in early socialisation; media is increasingly important but one of many intersecting agencies rather than the most powerful in all contexts.", acceptedAnswers: ["Media is growing in influence (7+ hours/day, social media, Baudrillard's hyperreality) but family, school and peers also powerfully socialise; media is one of many agents", "Strong case for media: postmodern identity construction, screen time. Strong case against: family is primary, education sustained, peers crucial in adolescence", "Uses and gratifications theory shows audiences are active not passive; media matters but so do family, school and religion; conclusion depends on context", "Media increasingly important especially for identity but family foundational in early years; no single agent is most powerful in all contexts"], marks: 8, hint: "Agree (postmodernism, screen time, hypodermic syringe model). Disagree (family, school, peers). Reach a clear, nuanced conclusion." },
    { question: "'Crime is caused by social factors, not individual ones.' Evaluate this sociological claim. (20 marks)", answer: "Social explanations: labelling theory (Becker) — deviance is a social construction; those labelled 'criminal' may adopt the label (self-fulfilling prophecy). Marxist view (Hall et al. 'Policing the Crisis') — crime statistics reflect policing priorities and moral panics, not actual crime rates. Merton's strain theory — crime results from blocked legitimate opportunities to achieve culturally valued goals (e.g. wealth). Subcultural theories (Cohen, Cloward and Ohlin) — criminal subcultures arise where legitimate means to success are unavailable. Chicago School: crime concentrated in deprived inner-city areas regardless of who lives there — social ecology. Individual explanations: biological (genetic predisposition, XYY chromosome research); psychological (personality factors — psychopathy, low impulse control); rational choice theory — crime is a rational decision weighing costs and benefits. Evaluation: crime statistics show clear patterns by class, ethnicity, age, and area — consistent with social explanations. However, individual factors cannot be entirely dismissed — most people in deprived areas do not offend. Interactionist view: crime results from the interaction between social structure and individual agency. Conclusion: a biopsychosocial model is most convincing; social factors are primary but interact with individual characteristics.", acceptedAnswers: ["Social factors (labelling, strain theory, subcultures) explain crime patterns by class/area; individual theories also relevant; interactionist synthesis most convincing", "Merton, Becker, Cohen all show social causes; biological/rational choice theories offer individual explanations; crime is best understood as an interaction of both", "Social ecology, subcultural theory and Marxist perspectives support social causes; biological and psychological theories support individual causes; both needed", "Strain theory and labelling support social causation; rational choice and psychology support individual; most crime is best explained socially but individuals matter too"], marks: 8, hint: "Present sociological (labelling, Marxism, strain theory) and individual (biological, rational choice) explanations. Evaluate each and form a clear conclusion." },
    { question: "Evaluate the view that social class is the most significant factor affecting life chances in Britain today. (20 marks)", answer: "Social class and life chances: Townsend showed working-class individuals are more likely to experience poverty, poor health, shorter life expectancy, and lower educational attainment. Middle and upper classes benefit from cultural capital (Bourdieu), superior education (private schooling), and social networks (social capital). Class background remains the strongest predictor of income in adulthood in the UK. Other factors: gender — women still earn less than men (pay gap ~18%) and face glass ceiling. Ethnicity — Black and Pakistani heritage adults face higher poverty rates and labour market discrimination. Age — young people face precarious employment; elderly face poverty in retirement. Disability — significant barriers to employment and independent living. Intersectionality (Crenshaw): these factors intersect and compound — a working-class Black woman faces multiple, overlapping disadvantages not reducible to any single factor. Evidence that class remains paramount: despite legal protections, private school pupils (~7% of students) make up ~40% of Russell Group undergraduates and dominate senior professions and politics. Evaluation: class remains very significant but contemporary sociology recognises a multi-dimensional picture. Postmodernists (Pakulski and Waters) argue class identities are fragmenting as consumption and identity become more fluid. Conclusion: class remains a major structural factor but interacts with gender, ethnicity, and age to produce complex, compounding inequalities.", acceptedAnswers: ["Class remains most significant (Bourdieu, private education data) but gender, ethnicity, age and disability intersect with class — intersectionality essential", "Strong evidence class shapes life chances but gender pay gap, ethnic discrimination and disability add layers — Crenshaw's intersectionality explains compounding disadvantage", "Class is powerful predictor but not the only factor — Townsend on class, plus gender/ethnicity/age evidence; postmodernists question class as a concept", "Class matters most statistically but interacts with other factors; private school dominance of elite professions shows class is still decisive"], marks: 8, hint: "Strong case for class (Bourdieu, statistics, private education). Then challenge with gender, ethnicity, age. Discuss intersectionality. Form a nuanced conclusion." },
    { question: "'Functionalism provides the best explanation of the role of religion in society.' Evaluate this view. (20 marks)", answer: "Functionalist view (Durkheim): religion performs social functions — social cohesion (collective rituals create a shared sense of belonging), moral community (reinforces shared norms and values), and collective conscience (sense of being part of something larger than the individual). Malinowski: religion manages life crises (death, uncertainty) that could threaten social stability. Parsons: religion provides ultimate meaning and reinforces core values. Supporting evidence: religious ceremonies (weddings, funerals) reinforce social solidarity. Against — Marxist view: religion is an ideological tool of the ruling class ('opium of the people' — Marx), used to legitimate class inequality and encourage acceptance of suffering. Feminist view: religion reinforces patriarchy — most world religions are male-dominated and place women in subordinate roles (Holm). Neo-Marxists and conflict theorists: religion can also be a force for social change — liberation theology in Latin America, Civil Rights movement (Martin Luther King). Evaluation of functionalism: provides a useful account of religion's integrating role but ignores internal conflict within religious communities and assumes religion is always a positive force. Secularisation challenges functionalist claims — in Britain, religion's social functions have been taken over by state institutions (welfare, education). Conclusion: functionalism captures important aspects of religion's social role but underestimates conflict, gender inequality, and the impact of secularisation.", acceptedAnswers: ["Functionalism explains cohesion (Durkheim) but Marxist (opium) and feminist (patriarchy) critiques show it ignores religion's negative aspects", "Durkheim's social cohesion function is useful but Marxist exploitation critique and feminist patriarchy critique challenge functionalism's positive view", "Functionalism: Durkheim, Malinowski, Parsons see religion as integrating. Critics: Marxists say it legitimates inequality; feminists say it oppresses women", "Functionalist strengths: explains ritual solidarity. Weaknesses: ignores conflict, patriarchy within religion, and secularisation undermining its claimed functions"], marks: 8, hint: "Present functionalist view in detail (Durkheim, Parsons, Malinowski). Counter with Marxist and feminist views. Assess strengths and limitations of each." },
    { question: "Evaluate the sociological explanations for gender differences in educational achievement. (20 marks)", answer: "Girls outperform boys at GCSE and A-level across most subjects in the UK. External factors favouring girls: McRobbie — changing female role models and aspirations; impact of feminism. Sue Sharpe's study (1970s vs 1990s) showed girls' priorities shifted from 'love and marriage' to 'careers and independence'. Labour market changes — more service sector jobs. Internal school factors: Mitsos and Browne — coursework favours female learning styles (sustained effort, organisation). Teacher interaction — Skelton found boys receive more attention but it is often negative/disciplinary. Laddish anti-school subculture among boys (Mac an Ghaill): peer pressure to underachieve. Against the narrative of 'boys underachieving': Epstein argues this creates a moral panic — the real issue is working-class boys and boys from certain ethnic groups, not 'boys' as a homogeneous group. Gender interacts with class and ethnicity. Middle-class boys perform well; it is specifically working-class and Black Caribbean boys who lag. Evaluation: single-variable (gender) explanations are insufficient. Intersectionality is essential — a working-class Black boy faces compounding disadvantages. The education system's approach to masculinity and learning styles deserves attention. Conclusion: gender differences in education are real but must be understood in intersection with class and ethnicity, not in isolation.", acceptedAnswers: ["Girls outperform boys due to changing aspirations (Sharpe), coursework (Mitsos/Browne), laddish culture; but class and ethnicity intersect — it is not simply 'boys underachieve'", "Female achievement gains explained by feminist influence and changed labour market; male underachievement linked to laddish subculture; but Epstein argues this is a moral panic", "External factors (role models, feminism) and internal (coursework, teacher interaction) explain gender gap; intersectionality with class/ethnicity complicates the picture", "Girls outperform boys overall but class and ethnicity are equally important — working-class boys of certain ethnicities underachieve most severely"], marks: 8, hint: "Give external and internal school factors. Challenge the 'boys underachieve' narrative with class/ethnicity. Use intersectionality. Conclude clearly." },
    { question: "Evaluate functionalist and Marxist explanations of the role of education in society. (20 marks)", answer: "Functionalist view: Durkheim argued education creates social solidarity — teaching shared culture and values binds society together. Parsons: education is a bridge between the particularistic values of the family and the universalistic values of wider society, preparing pupils for adult roles through meritocratic selection. Davis and Moore: education allocates the most talented to the most important roles — inequality is functionally necessary. Marxist view: Bowles and Gintis ('Schooling in Capitalist America', 1976) — the correspondence principle shows school reproduces the social relations of the workplace. The hidden curriculum teaches obedience and conformity, not independent thought. Myth of meritocracy: education legitimates class inequality by making it appear fair and based on ability. Althusser: education is an Ideological State Apparatus that transmits ruling-class ideology. Evaluation of functionalism: assumes schools are truly meritocratic — ignores evidence that class background predicts achievement far better than ability (cultural capital, Bourdieu). Assumes all education serves everyone equally. Evaluation of Marxism: deterministic — ignores how individual agency can resist the system. Ignores ethnicity and gender (focuses only on class). Willis ('Learning to Labour', 1977): working-class 'lads' actively resist school culture rather than passively accepting it. Overall: both perspectives capture important aspects — functionalism explains the integrating and selecting functions; Marxism exposes structural inequality and ideological reproduction. Neither alone is sufficient.", acceptedAnswers: ["Functionalism: meritocracy and socialisation (Parsons/Durkheim); Marxism: hidden curriculum and correspondence principle (Bowles/Gintis); both have strengths and weaknesses", "Durkheim and Parsons see education as functional; Bowles and Gintis show it reproduces inequality; Willis shows agency resists determinism", "Functionalism explains solidarity and role allocation; Marxism exposes ideological reproduction and myth of meritocracy; neither is complete alone", "Both perspectives offer important insights — functionalism on integration, Marxism on inequality — but intersecting with gender, ethnicity, and individual agency"], marks: 12, hint: "Functionalism: Durkheim (solidarity), Parsons (meritocracy), Davis and Moore. Marxism: Bowles/Gintis (correspondence), Althusser. Evaluate both with examples and other perspectives." },
    { question: "Discuss sociological explanations for changing family structures in the UK. (20 marks)", answer: "Key changes: rise in cohabitation (from 5% of couples in 1970 to over 20% now), rising divorce rates (peak in 1993, but stabilised — about 42% of marriages end in divorce), increase in lone-parent families (now ~25% of UK families), same-sex families (Civil Partnership Act 2004, Marriage (Same Sex Couples) Act 2013), beanpole family structure (fewer siblings, more generations). Explanations: Secularisation — declining religious influence means divorce and cohabitation carry less stigma. Legal changes — Divorce Reform Act (1969) made divorce cheaper and more accessible. Changing role of women — feminist gains in education and employment mean women are less economically dependent on marriage. New Right (Murray) — welfare state enables lone parenthood by providing financial support, undermining traditional family. Postmodern view (Stacey): the family is more diverse, fluid, and individually constructed — no single 'normal' family exists. Beck's 'risk society': relationships are more uncertain; individuals make reflexive choices about family rather than following tradition. Feminist view: changing families reflect women's growing independence and rejection of patriarchal constraints. Evaluation: most sociologists see change as diverse rather than declining — the family institution remains but takes multiple forms. Functionalists worry about social instability; postmodernists celebrate diversity. Evidence: birth rates outside marriage have risen to over 50% in the UK — showing cohabitation and its dissolution are now mainstream.", acceptedAnswers: ["Secularisation, legal change, women's independence, and postmodern diversity all explain changing families; New Right sees decline, postmodernists see diversity", "Rising divorce, cohabitation, lone-parent families explained by legal reform, secularisation, feminism and changing attitudes", "Divorce Reform Act, secularisation, women's employment, and postmodern choice all contribute to family diversity in the UK", "Family structures diversifying: cohabitation, lone parenthood, same-sex families — explained by secularisation, feminism, legal change and postmodern individualism"], marks: 12, hint: "Name key changes (divorce, cohabitation, lone-parent), give multiple sociological explanations (legal, secular, feminist, postmodern), and evaluate different perspectives." },
  ],
  flashcard: [
    { term: "Functionalism", definition: "Society as a system of interconnected parts, each performing a function to maintain stability (consensus). Key theorists: Durkheim, Parsons, Merton. Education socialises and allocates roles.", example: "Education functions to socialise children and allocate roles through meritocracy (Parsons)" },
    { term: "Marxism", definition: "Conflict perspective: society based on class struggle between bourgeoisie (ruling class, own means of production) and proletariat (working class). Inequality is structural and serves capitalism.", example: "Bowles and Gintis: schools reproduce class inequality through the correspondence principle" },
    { term: "Feminism", definition: "Gender inequality and subordination of women. Liberal feminists: legal reform (Equal Pay Act). Radical feminists: patriarchy must be dismantled. Marxist feminists: gender inequality serves capitalism.", example: "Oakley's dual burden: women work a double shift — paid employment AND most domestic labour" },
    { term: "Interactionism", definition: "Focuses on small-scale, face-to-face interactions and how individuals construct meaning. Labelling theory: labels given by others shape identity and behaviour. Key: Becker, Goffman.", example: "Teachers label pupils as 'bright' or 'troublemaker'; labels influence performance (self-fulfilling prophecy)" },
    { term: "Hidden Curriculum", definition: "Informal lessons learned at school beyond formal content — punctuality, obedience, conformity, acceptance of hierarchy. Marxists argue it reproduces class inequality for capitalism.", example: "Bowles and Gintis (1976): school prepares working-class for obedience and middle-class for authority" },
    { term: "Norms and Values", definition: "Norms: unwritten rules of expected behaviour (e.g. queuing). Values: core beliefs underpinning norms (e.g. fairness, respect). Both transmitted through primary and secondary socialisation.", example: "Shaking hands (norm); honesty (value); both learned through socialisation in the family" },
    { term: "Social Mobility", definition: "Movement between social classes. Upward: higher class. Downward: lower class. Intergenerational: compared to parents. UK has low social mobility relative to comparable nations.", example: "Working-class student becoming a doctor = upward social mobility" },
    { term: "Labelling Theory (Becker)", definition: "Deviance is not a quality of the act but of society's reaction to it. Being labelled 'deviant' or 'criminal' can create a self-fulfilling prophecy where the labelled person acts accordingly.", example: "Howard Becker: 'Outsiders' (1963) — moral entrepreneurs create and apply deviant labels" },
    { term: "Ethnicity and Achievement", definition: "Chinese and Indian heritage students outperform the national average. Black Caribbean students underachieve relative to potential. Explanations: racism, labelling, material deprivation, cultural capital variation, ethnocentric curriculum.", example: "Gillborn: Black pupils more likely to be placed in lower sets and excluded — structural racism" },
    { term: "Secularisation", definition: "Declining social significance of religion in modern society — falling church attendance, reduced political/legal influence of religion, fewer people identifying as religious.", example: "UK church attendance declined from ~40% (1900) to under 5% (2020s)" },
    { term: "Moral Panic (Cohen)", definition: "A disproportionate public reaction to a perceived social threat, amplified by media coverage. A 'folk devil' is identified; police and courts crack down; the problem may actually increase through labelling.", example: "Stanley Cohen (1972): mods and rockers — media coverage created a disproportionate moral panic" },
    { term: "Strain Theory (Merton)", definition: "Crime results from a gap between culturally valued goals (e.g. wealth) and the legitimate means to achieve them. Responses: conformity, innovation (crime), ritualism, retreatism, rebellion.", example: "Working-class person denied legitimate route to wealth may 'innovate' by turning to crime" },
    { term: "Cultural Capital (Bourdieu)", definition: "The attitudes, knowledge, language (elaborated code), and social skills that middle-class families possess which are valued by schools. Gives their children a structural educational advantage.", example: "Middle-class parents more able to choose better schools, help with homework, and use elaborated code" },
    { term: "Patriarchy", definition: "A social system in which men hold primary power and privilege. Feminists argue patriarchy is embedded in institutions (family, religion, media, work) and systematically disadvantages women.", example: "Walby's 'six structures of patriarchy': work, household, culture, sexuality, violence, state" },
    { term: "Uses and Gratifications Theory", definition: "Audiences are active, not passive. People choose media to meet specific needs: information, identity, integration and social interaction, and entertainment (Blumler and Katz).", example: "A person watches news for information; soap operas for social interaction topics — active choices" },
    { term: "Validity and Reliability in Sociological Research", definition: "Validity: research measures what it claims to — qualitative methods tend to be more valid. Reliability: results can be replicated — quantitative methods tend to be more reliable. There is a trade-off.", example: "Official crime statistics: reliable (consistent) but low validity (under-reporting, dark figure)" },
    { term: "Primary Socialisation", definition: "The first and most fundamental stage of socialisation, occurring in the family. Children learn basic norms, values, language, and identity. Functionalists see this as the family's most important function.", example: "A child learns to say 'please' and 'thank you' and to share — basic norms taught by parents" },
    { term: "Secondary Socialisation", definition: "Socialisation that occurs outside the family through school, peer groups, media, religion and work. Reinforces and builds on primary socialisation throughout life.", example: "School teaches punctuality and obedience; peer groups teach social norms of the youth culture" },
    { term: "Correspondence Principle (Bowles and Gintis)", definition: "The social relations of schooling mirror those of the workplace. Hierarchy, grades for effort (not content), obedience to teachers — all correspond to the employment relationship, reproducing capitalism.", example: "Students obey teachers for grades just as workers obey bosses for wages — school mirrors work" },
    { term: "Anomie (Durkheim)", definition: "A state of normlessness where social rules break down or become unclear. Durkheim linked it to higher suicide rates. Merton adapted it to explain crime when legitimate means are blocked.", example: "Rapid social change (industrialisation) can produce anomie — people lose clear social rules to follow" },
    { term: "Social Control", definition: "The mechanisms by which society encourages conformity to norms. Formal: police, courts, prisons (legal sanctions). Informal: family shame, peer pressure, community gossip, religious teaching.", example: "Police arrest (formal); parents expressing disappointment (informal) — both enforce social norms" },
    { term: "Self-Fulfilling Prophecy", definition: "A prediction that comes true because people act as if it is true. In education: a teacher labels a pupil as 'thick'; the pupil internalises the label and underachieves, fulfilling the prediction.", example: "Rosenthal and Jacobson (1968): 'Pygmalion in the Classroom' — high teacher expectations raised IQ scores" },
    { term: "Dark Figure of Crime", definition: "The amount of crime committed but never recorded in official statistics — because it is unreported by victims (embarrassment, fear, distrust of police) or unrecorded by police (discretion, recording practices).", example: "Domestic violence and rape are massively under-reported — the dark figure for these crimes is very large" },
    { term: "Dual Burden (Oakley)", definition: "Women perform a 'double shift' — paid employment plus the majority of domestic labour and childcare at home. Oakley argues this reflects and reproduces gender inequality in the family.", example: "A woman working full-time still does most of the cooking, cleaning and childcare in the evenings" },
    { term: "Social Stratification", definition: "The division of society into hierarchical layers (strata) based on wealth, status, and power. Systems include: caste (closed — India), feudalism (closed — medieval Europe), and class (open).", example: "The UK class system: upper, middle, working class — movement between them is possible (open system)" },
    { term: "Weberian Stratification", definition: "Max Weber's three-dimensional model of inequality: class (economic position), status (social prestige), and party (political power). These dimensions can diverge — high income does not guarantee high status.", example: "A drug dealer may have high income (class) but low status; a vicar may have high status but low income" },
    { term: "Bourgeoisie and Proletariat (Marx)", definition: "The bourgeoisie own the means of production (factories, land) and exploit the proletariat (workers who sell their labour). Class conflict between them drives social change in Marxist theory.", example: "Factory owner (bourgeoisie) profits from workers (proletariat) who produce goods but receive only wages" },
    { term: "Cohabitation", definition: "An unmarried couple living together in a romantic relationship. Increased dramatically in the UK since the 1970s — now over 20% of couples. Associated with secularisation and changing attitudes to marriage.", example: "Over 20% of UK couples now cohabit rather than marry — seen as an alternative or precursor to marriage" },
    { term: "Reconstituted (Blended) Family", definition: "A family formed when two adults with children from previous relationships live together. Also called a step-family. Increasingly common due to rising divorce and remarriage rates.", example: "A woman with two children marrying a man with one child creates a reconstituted family of five" },
    { term: "Positivism vs Interpretivism", definition: "Positivism: sociology should use scientific, objective, quantitative methods to find social laws (Durkheim). Interpretivism: sociology should understand subjective meanings through qualitative methods (Weber, Becker).", example: "Durkheim studied suicide using statistics (positivist); Becker used observation to study deviance (interpretivist)" },
    { term: "Participant Observation", definition: "The researcher joins the group being studied. Overt: group knows. Covert: researcher conceals their role. Produces valid, rich qualitative data but raises ethical issues and risks researcher going native.", example: "Whyte 'Street Corner Society' (1943): lived with Italian-American gang for 3 years — covert participant observation" },
    { term: "Intersectionality (Crenshaw)", definition: "The idea that different dimensions of inequality (class, gender, ethnicity, age, disability) overlap and compound, creating unique and complex disadvantages not reducible to any single factor.", example: "A Black working-class woman faces layered disadvantages from racism, sexism, and class simultaneously" },
  ],
};
